import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { serverRootPassword } from "@/lib/sftp";
import { vmStatus, listSnapshots, listBackups } from "@/lib/proxmox";
import { AutoRefresh } from "@/components/AutoRefresh";
import { ServerControls } from "@/components/ServerControls";
import { RenewalCard } from "@/components/SubscriptionControls";
import { StatusDot, Badge, fmtBytes, fmtMoney } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { ServerTabs } from "@/components/customer/ServerTabs";
import { MetricsPanel } from "@/components/customer/MetricsPanel";
import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
import { ServerRename } from "@/components/customer/ServerRename";
import { Console } from "@/components/customer/Console";
import { OpenTerminalButton } from "@/components/customer/OpenTerminalButton";
import { FileManager } from "@/components/customer/FileManager";
import { CopyText, RevealPassword, ResetPasswordButton } from "@/components/customer/ServerAccess";
import { ProjectAssign } from "@/components/customer/ProjectAssign";
import { CreateSnapshotForm, SnapshotActions } from "@/components/customer/SnapshotControls";
import { CreateBackupButton } from "@/components/customer/BackupControls";
import { AddForwardForm, DeleteForwardButton, FirewallPresets } from "@/components/customer/NetworkingControls";
import { ResizePicker } from "@/components/customer/ResizePicker";
import { ResizeDown } from "@/components/customer/ResizeDown";
import { AddStorage } from "@/components/customer/AddStorage";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { effectiveDiskGB } from "@/lib/extra-disk";
import { ReinstallOs } from "@/components/customer/ReinstallOs";
import { BackupSchedule } from "@/components/customer/BackupSchedule";
import { ActivityTimeline } from "@/components/customer/ActivityTimeline";
import { SftpAccess } from "@/components/customer/SftpAccess";
import { GameAutoUpdate } from "@/components/customer/GameAutoUpdate";
import { BackupRestore } from "@/components/customer/BackupRestore";
import { GameSettings } from "@/components/customer/GameSettings";
import { ControlPanel } from "@/components/customer/cpanel/ControlPanel";
import { GAME_FAMILIES, type GameFamily } from "@/lib/games";
import { familyFor, schemaFor, isValidVariant, validateConfig } from "@/lib/game-config";

export const dynamic = "force-dynamic";

function fmtUptime(seconds: number): string {
  if (!seconds || seconds <= 0) return "—";
  const d = Math.floor(seconds / 86400);
  const h = Math.floor((seconds % 86400) / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
}

type LiveStats = {
  cpu?: number;
  mem?: number;
  maxmem?: number;
  uptime?: number;
  netin?: number;
  netout?: number;
} | null;

export default async function ServerPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string }>;
}) {
  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id },
    include: {
      plan: true,
      osTemplate: true,
      project: true,
      portForwards: { orderBy: { publicPort: "asc" } },
      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
      dedicatedIp: true,
    },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();

  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
  // display value through the decrypt fallback (legacy plaintext rows still work).
  const rootPassword = serverRootPassword(server);

  const [projects, activePlans, osTemplates, extraDiskPriceCents] = await Promise.all([
    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({
      where: { active: true, category: "PLAIN_OS" },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    }),
    extraDiskPerGbCents(),
  ]);

  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);

  const publicIp = process.env.PUBLIC_IP ?? "";
  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
  const busy =
    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
  const steady = ["RUNNING", "STOPPED"].includes(server.status);

  let live: LiveStats = null;
  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
  let backups: { volid: string; ctime?: number; size?: number }[] = [];
  let pveUnavailable = false;

  if (server.vmid && steady) {
    const results = await Promise.allSettled([
      vmStatus(server.vmid),
      listSnapshots(server.vmid),
      listBackups(server.vmid),
    ]);
    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
    pveUnavailable = results.some((r) => r.status === "rejected");
  }

  const sshCommand = server.sshPort ? `ssh root@${publicIp} -p ${server.sshPort}` : null;

  // Single-item terminal list for this server — connect string computed the
  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
  const terminalServers = [
    {
      id: server.id,
      hostname: server.hostname,
      connect: server.dedicatedIp
        ? `ssh root@${server.dedicatedIp.address}`
        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
    },
  ];

  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
  const dedicated = !!server.dedicatedIp;
  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
  const sftpPort = dedicated ? 22 : server.sshPort;
  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);

  // Per-game customization (only for game servers with a customization schema).
  const gameFamily = familyFor(server);
  const gameSchema = schemaFor(gameFamily);
  const gameVariant =
    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
      ? server.gameVariant
      : gameSchema?.defaultVariant ?? "";
  const gameValidated = gameFamily
    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
    : null;
  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};

  /* ---------- Tab: Overview ---------- */
  const overview = (
    <div className="grid gap-6 md:grid-cols-2">
      <div className="card">
        <h2 className="mb-4 font-semibold">Access</h2>
        <dl className="space-y-3 text-sm">
          <div>
            <dt className="text-slate-400">SSH command</dt>
            <dd className="mt-1 flex items-center gap-2">
              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
                {sshCommand ?? "provisioning…"}
              </code>
              {sshCommand && <CopyText text={sshCommand} />}
            </dd>
          </div>
          <div className="flex items-center justify-between">
            <dt className="text-slate-400">Root password</dt>
            <dd>
              {rootPassword ? (
                <RevealPassword password={rootPassword} />
              ) : (
                <span className="text-slate-500">—</span>
              )}
            </dd>
          </div>
          <div className="flex items-center justify-between">
            <dt className="text-slate-400">Private IP</dt>
            <dd className="font-mono text-xs">{server.ipAddress ?? "—"}</dd>
          </div>
        </dl>
        <div className="divider" />
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-xs text-slate-500">
            Lost access or rotating credentials? Generate a fresh root password.
          </p>
          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
        </div>
      </div>

      <SftpAccess
        host={sftpHost}
        port={sftpPort}
        password={rootPassword}
        dedicated={dedicated}
      />

      {isGameServer && (
        <div className="md:col-span-2">
          <GameAutoUpdate
            serverId={server.id}
            gameName={server.osTemplate.name}
            autoUpdate={server.autoUpdate}
            canUpdate={server.status === "RUNNING"}
            busy={busy}
          />
        </div>
      )}

      {server.gamePlanId && gameSchema && (
        <div className="md:col-span-2">
          <GameSettings
            serverId={server.id}
            schema={gameSchema}
            variant={gameVariant}
            values={gameValues}
            disabled={busy || !steady}
          />
        </div>
      )}

      <div className="card">
        <h2 className="mb-4 font-semibold">Live stats</h2>
        {live ? (
          <div className="space-y-4 text-sm">
            <div>
              <div className="mb-1.5 flex justify-between">
                <span className="text-slate-400">CPU</span>
                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
              </div>
              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
            </div>
            <div>
              <div className="mb-1.5 flex justify-between">
                <span className="text-slate-400">Memory</span>
                <span className="font-semibold">
                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
                </span>
              </div>
              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Uptime</span>
              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Network I/O</span>
              <span className="font-mono text-xs">
                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
              </span>
            </div>
          </div>
        ) : (
          <p className="text-sm text-slate-400">
            {pveUnavailable
              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
              : "Live stats appear once the server is provisioned."}
          </p>
        )}
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Configuration</h2>
        <dl className="space-y-2.5 text-sm">
          <div className="flex justify-between">
            <dt className="text-slate-400">Plan</dt>
            <dd>
              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
              {totalDiskGB} GB NVMe
              {server.extraDiskGB > 0 && (
                <span className="block text-xs text-slate-500">
                  {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
                </span>
              )}
            </dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">Bandwidth</dt>
            <dd>{server.plan.bandwidthTB} TB / month</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">Operating system</dt>
            <dd>{server.osTemplate.name}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">Created</dt>
            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
          </div>
          <div className="flex justify-between">
            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
            <dd>
              {server.isFree
                ? "Free — never expires"
                : server.expiresAt
                  ? server.expiresAt.toISOString().slice(0, 10)
                  : "—"}
            </dd>
          </div>
        </dl>
      </div>

      {!server.isFree ? (
        <RenewalCard
          serverId={server.id}
          autoRenew={server.autoRenew}
          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
          priceCents={server.plan.priceCents}
          extraDiskGB={server.extraDiskGB}
          extraDiskMonthlyCents={server.extraDiskGB * extraDiskPriceCents}
          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
        />
      ) : (
        <div className="card">
          <h2 className="mb-3 font-semibold">Subscription</h2>
          <p className="text-sm text-slate-400">
            This server is free of charge — no billing, no expiry.
          </p>
        </div>
      )}

      <div className="card md:col-span-2">
        <h2 className="mb-4 font-semibold">Disk usage</h2>
        <DiskUsageChart
          serverId={server.id}
          planTotalGB={totalDiskGB}
          available={!!server.vmid && steady}
        />
      </div>

      <div className="card md:col-span-2">
        <h2 className="mb-3 font-semibold">Project</h2>
        <ProjectAssign
          serverId={server.id}
          currentProjectId={server.projectId}
          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
        />
      </div>
    </div>
  );

  /* ---------- Tab: Files ---------- */
  const filesPanel =
    server.status === "RUNNING" ? (
      <FileManager serverId={server.id} />
    ) : (
      <div className="card py-12 text-center">
        <h2 className="font-semibold">File manager unavailable</h2>
        <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
          The in-browser file manager works only while your server is{" "}
          <span className="font-medium text-slate-200">running</span>. Start the server to browse,
          upload, and edit files over SFTP.
        </p>
      </div>
    );

  /* ---------- Tab: Snapshots ---------- */
  const snapshotsTab = (
    <div className="space-y-6">
      <div className="card">
        <h2 className="mb-4 font-semibold">Create snapshot</h2>
        <CreateSnapshotForm serverId={server.id} disabled={busy || !steady} />
      </div>
      <div className="card p-0">
        <p className="section-label px-4 pt-4">Snapshots</p>
        {pveUnavailable && snapshots.length === 0 ? (
          <p className="px-4 py-6 text-sm text-amber-300">
            Could not load snapshots — the hypervisor is briefly unavailable. Try again in a moment.
          </p>
        ) : snapshots.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No snapshots yet. Take one before risky changes so you can roll back instantly.
          </p>
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th>Taken</th>
                <th>Description</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {snapshots.map((s) => (
                <tr key={s.name}>
                  <td className="font-mono text-xs">{s.name}</td>
                  <td className="text-slate-400">
                    {s.snaptime ? new Date(s.snaptime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
                  </td>
                  <td className="text-slate-400">{s.description || "—"}</td>
                  <td>
                    <SnapshotActions serverId={server.id} name={s.name} disabled={busy || !steady} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      <p className="text-xs text-slate-500">
        Snapshots live on the same storage as your server — use backups for disaster recovery.
      </p>
    </div>
  );

  /* ---------- Tab: Backups ---------- */
  // Latest backup/restore job (server.jobs is desc by createdAt) — seeds the
  // live progress bar so a reloaded page shows an in-flight job without a flash.
  const latestBackupJob = server.jobs.find(
    (j) => j.type === "BACKUP_CREATE" || j.type === "BACKUP_RESTORE"
  );
  const initialBackupJob = latestBackupJob
    ? {
        id: latestBackupJob.id,
        type: latestBackupJob.type as "BACKUP_CREATE" | "BACKUP_RESTORE",
        status: latestBackupJob.status as "QUEUED" | "RUNNING" | "DONE" | "FAILED",
        progress: latestBackupJob.progress,
        step: latestBackupJob.step,
        error: latestBackupJob.error,
        createdAt: latestBackupJob.createdAt.toISOString(),
      }
    : null;
  const backupsTab = (
    <div className="space-y-6">
      <BackupSchedule
        serverId={server.id}
        autoBackup={server.autoBackup}
        backupIntervalHours={server.backupIntervalHours}
        lastAutoBackup={server.lastAutoBackup ? server.lastAutoBackup.toISOString() : null}
      />
      <div className="card space-y-4">
        <div>
          <h2 className="font-semibold">Backups</h2>
          <p className="mt-1 text-sm text-slate-400">
            Full-image backups stored on a separate 4 TB pool, independent from your server&apos;s NVMe storage.
          </p>
        </div>
        <CreateBackupButton
          serverId={server.id}
          disabled={busy || !steady}
          initialJob={initialBackupJob}
        />
      </div>
      <div className="card p-0">
        {pveUnavailable && backups.length === 0 ? (
          <p className="px-4 py-6 text-sm text-amber-300">
            Could not load backups — the hypervisor is briefly unavailable. Try again in a moment.
          </p>
        ) : backups.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No backups yet. Create one now — restores are handled by support within minutes.
          </p>
        ) : (
          <table className="table-shell">
            <thead>
              <tr>
                <th>Backup</th>
                <th>Created</th>
                <th className="text-right">Size</th>
              </tr>
            </thead>
            <tbody>
              {backups.map((b) => (
                <tr key={b.volid}>
                  <td className="font-mono text-xs">{b.volid.split("/").pop()}</td>
                  <td className="text-slate-400">
                    {b.ctime ? new Date(b.ctime * 1000).toISOString().slice(0, 16).replace("T", " ") : "—"}
                  </td>
                  <td className="text-right text-slate-400">{fmtBytes(b.size ?? 0)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
      <BackupRestore
        serverId={server.id}
        backups={backups}
        unavailable={pveUnavailable}
        disabled={busy || !steady}
      />
    </div>
  );

  /* ---------- Tab: Networking ---------- */
  const networking = (
    <div className="space-y-6">
      <div className="glass p-4 text-sm text-slate-300">
        Your server sits behind NAT on a private network ({server.ipAddress ?? "10.20.0.x"}). Public
        ports on <span className="font-mono text-brand-300">{publicIp}</span> are forwarded to ports
        inside your VM — connect to{" "}
        <span className="font-mono text-brand-300">{publicIp}:&lt;public port&gt;</span> to reach a
        forwarded service.
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Port forwards</p>
        <table className="table-shell mt-2">
          <thead>
            <tr>
              <th>Public endpoint</th>
              <th>Guest port</th>
              <th>Protocol</th>
              <th className="text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td className="font-mono text-xs">
                {server.sshPort ? `${publicIp}:${server.sshPort}` : "—"}
              </td>
              <td className="font-mono text-xs">22</td>
              <td className="text-slate-400">tcp</td>
              <td className="text-right">
                <Badge tone="slate">SSH — managed</Badge>
              </td>
            </tr>
            {server.portForwards.map((f) => (
              <tr key={f.id}>
                <td className="font-mono text-xs">
                  {publicIp}:{f.publicPort}
                </td>
                <td className="font-mono text-xs">{f.guestPort}</td>
                <td className="text-slate-400">{f.protocol}</td>
                <td className="text-right">
                  <DeleteForwardButton serverId={server.id} forwardId={f.id} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {server.portForwards.length === 0 && (
          <p className="px-4 pb-4 text-sm text-slate-500">
            No custom forwards yet — add one below to expose a web server, game server, or any other
            service.
          </p>
        )}
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Quick firewall presets</h2>
        <FirewallPresets
          serverId={server.id}
          disabled={busy || !steady}
          existingGuestPorts={server.portForwards.map((f) => f.guestPort)}
        />
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Add port forward</h2>
        <AddForwardForm serverId={server.id} />
        <p className="mt-3 text-xs text-slate-500">
          A free public port (20000–29999) is assigned automatically. Up to 10 forwards per server.
        </p>
      </div>
    </div>
  );

  /* ---------- Tab: Resize ---------- */
  const resize = (
    <div className="space-y-6">
      {/* Disk-only growth sits ABOVE the plan pickers: most customers who come
          here just need more space, and this is the cheap answer that leaves
          their CPU/RAM/price alone. One-way — see the component. */}
      <AddStorage
        serverId={server.id}
        hostname={server.hostname}
        planDiskGB={server.plan.diskGB}
        extraDiskGB={server.extraDiskGB}
        pricePerGbCents={extraDiskPriceCents}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        isFree={server.isFree}
        walletBalanceCents={user.balanceCents}
        disabled={busy || !steady}
      />

      <ResizePicker
        serverId={server.id}
        currentPlanId={server.planId}
        currentDiskGB={server.plan.diskGB}
        currentPriceCents={server.plan.priceCents}
        extraDiskGB={server.extraDiskGB}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        isFree={server.isFree}
        walletBalanceCents={user.balanceCents}
        plans={activePlans.map((p) => ({
          id: p.id,
          name: p.name,
          cpuCores: p.cpuCores,
          ramMB: p.ramMB,
          diskGB: p.diskGB,
          bandwidthTB: p.bandwidthTB,
          priceCents: p.priceCents,
        }))}
        disabled={busy || !steady}
      />

      <ResizeDown
        serverId={server.id}
        currentPlanId={server.planId}
        currentDiskGB={server.plan.diskGB}
        currentPriceCents={server.plan.priceCents}
        termMonths={server.termMonths}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        isFree={server.isFree}
        plans={activePlans.map((p) => ({
          id: p.id,
          name: p.name,
          cpuCores: p.cpuCores,
          ramMB: p.ramMB,
          diskGB: p.diskGB,
          bandwidthTB: p.bandwidthTB,
          priceCents: p.priceCents,
        }))}
        disabled={busy || !steady}
      />

      {/* Image minimum-disk checks run against the EFFECTIVE disk (totalDiskGB):
          a server that bought extra storage really does have room for a larger
          image than its plan alone would allow. */}
      <ReinstallOs
        serverId={server.id}
        currentOsTemplateId={server.osTemplateId}
        currentOsName={server.osTemplate.name}
        planRamMB={server.plan.ramMB}
        planDiskGB={totalDiskGB}
        templates={osTemplates.map((t) => ({
          id: t.id,
          name: t.name,
          family: t.family,
          version: t.version,
          minRamMB: t.minRamMB,
          minDiskGB: t.minDiskGB,
        }))}
        disabled={busy || !steady}
      />
    </div>
  );

  /* ---------- Tab: Activity ---------- */
  const planNames: Record<string, string> = Object.fromEntries(
    activePlans.map((p) => [p.id, p.name])
  );
  const activity = (
    <div className="card p-0">
      <p className="section-label px-5 pt-4">Deployment & lifecycle timeline</p>
      <ActivityTimeline jobs={server.jobs} planNames={planNames} />
