        <h2 className="font-semibold">Console unavailable</h2>
        <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
          The VNC console is available only while your server is{" "}
          <span className="font-medium text-slate-200">running</span>. Start the server to open a
          graphical session.
        </p>
      </div>
    );

  return (
    <div>
      {busy && <AutoRefresh />}

      <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex flex-wrap items-center gap-3">
            <h1 className="page-title">{server.label || server.name}</h1>
            <StatusDot status={server.status} />
            <ServerRename serverId={server.id} label={server.label} fallback={server.name} />
