          <div className="mt-2 flex flex-wrap items-center gap-2">
            <span className="font-mono text-xs text-slate-500">{server.hostname}</span>
            <Badge tone="slate">{server.plan.name}</Badge>
            <Badge tone="slate">{server.osTemplate.name}</Badge>
            {server.isFree && <Badge tone="brand">free</Badge>}
            {!server.isFree && (
              <Badge tone="slate">{fmtMoney(server.plan.priceCents)}/mo</Badge>
            )}
          </div>
        </div>
        {server.status !== "SUSPENDED" && !transitional && (
          <div className="flex flex-wrap items-center gap-2">
            {server.status === "RUNNING" && <OpenTerminalButton servers={terminalServers} />}
            <ServerControls serverId={server.id} status={server.status} busy={busy} />
          </div>
        )}
      </div>

      {server.status === "SUSPENDED" && (
        <div className="card mb-6 border-red-500/30 text-sm text-red-300">
          This server has been suspended{server.suspendedNote ? `: ${server.suspendedNote}` : "."}{" "}
          Contact support if you believe this is a mistake.
        </div>
      )}

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          {server.status === "DELETING"
            ? "Your server is being deleted…"
            : "Your server is being set up — this usually takes under two minutes. The page refreshes automatically."}
        </div>
      )}

      <ServerTabs
        initialTab={tab}
        overview={overview}
        controlPanel={<ControlPanel serverId={server.id} running={server.status === "RUNNING"} />}
        metrics={<MetricsPanel serverId={server.id} />}
        console={consolePanel}
        files={filesPanel}
        snapshots={snapshotsTab}
        backups={backupsTab}
        networking={networking}
        resize={resize}
        activity={activity}
      />
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";

const TABS = [
  "Overview",
  "Control panel",
  "Metrics",
  "Console",
  "Files",
  "Snapshots",
  "Backups",
  "Networking",
  "Resize",
  "Activity",
] as const;

export function ServerTabs({
  initialTab,
  overview,
  controlPanel,
  metrics,
  console: consolePanel,
  files,
  snapshots,
  backups,
  networking,
  resize,
  activity,
}: {
  initialTab?: string;
  overview: ReactNode;
  controlPanel: ReactNode;
  metrics: ReactNode;
  console: ReactNode;
  files: ReactNode;
  snapshots: ReactNode;
  backups: ReactNode;
  networking: ReactNode;
  resize: ReactNode;
  activity: ReactNode;
}) {
  const keys = TABS.map((t) => t.toLowerCase());
  const [tab, setTab] = useState<string>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
  );

  const panels: Record<string, ReactNode> = {
    overview,
    "control panel": controlPanel,
    metrics,
    console: consolePanel,
    files,
    snapshots,
    backups,
    networking,
    resize,
    activity,
  };

  return (
    <div>
      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
        {TABS.map((t) => {
          const k = t.toLowerCase();
          const active = tab === k;
          return (
            <button
              key={k}
              type="button"
              onClick={() => {
                setTab(k);
                window.history.replaceState(null, "", `?tab=${k}`);
              }}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );
}
