export const dynamic = "force-dynamic";

export default async function ServersPage() {
  const user = await requireUser();
  const servers = await db.server.findMany({
    where: { userId: user.id },
    include: { plan: true, osTemplate: true, project: true },
    orderBy: { createdAt: "desc" },
  });

  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  const rows: ServerRow[] = servers.map((s) => ({
    id: s.id,
    hostname: s.hostname,
    status: s.status,
    isFree: s.isFree,
    // Effective disk = plan allowance + any separately-purchased extra disk.
    planLine: `${s.plan.name} · ${s.plan.cpuCores} vCPU · ${s.plan.ramMB / 1024} GB · ${effectiveDiskGB(s.plan.diskGB, s.extraDiskGB)} GB`,
    osName: s.osTemplate.name,
    project: s.project ? { name: s.project.name, color: s.project.color } : null,
    endpoint: s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : null,
    created: s.createdAt.toISOString().slice(0, 10),
  }));

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PageHeader title="Servers" sub="All virtual machines on your account.">
        <Link href="/dashboard/deploy" className="btn-primary">
