"use client";

import { useState } from "react";
import { WebsitesPanel } from "./WebsitesPanel";
import { DatabasesPanel } from "./DatabasesPanel";
import { AppsPanel } from "./AppsPanel";
import { CronServicesPanel } from "./CronServicesPanel";

const SUBTABS = [
  { key: "websites", label: "Websites & PHP" },
  { key: "databases", label: "Databases" },
  { key: "apps", label: "One-click apps" },
  { key: "services", label: "Cron & Services" },
] as const;

/**
 * Grouped "Control panel" tab on the server detail page — a cPanel/Plesk-style
 * manager for the customer's own VPS, themed to match Nxeon. Keeps the four
 * bundles behind a single main tab with lightweight inner tabs so the page stays
 * readable. Each panel loads its own data client-side (loading/empty/error
 * states throughout) via the sandbox-gated server actions.
 */
export function ControlPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [tab, setTab] = useState<string>("websites");

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-1.5">
        {SUBTABS.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              className={`rounded-xl px-3.5 py-1.5 text-sm font-medium transition-colors ${
                active
                  ? "bg-white/[0.08] text-white ring-1 ring-inset ring-brand-500/40"
                  : "text-slate-400 hover:bg-white/[0.04] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "websites" && <WebsitesPanel serverId={serverId} running={running} />}
        {tab === "databases" && <DatabasesPanel serverId={serverId} running={running} />}
        {tab === "apps" && <AppsPanel serverId={serverId} running={running} />}
        {tab === "services" && <CronServicesPanel serverId={serverId} running={running} />}
      </div>
    </div>
  );
}
"use client";

import { useState } from "react";

/** Status pill matching the Nxeon theme, coloured by lifecycle state. */
export function StatusPill({ status }: { status: string }) {
  const s = status.toUpperCase();
  const tone =
    s === "ACTIVE"
      ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
      : s === "FAILED"
        ? "border-red-500/30 bg-red-500/10 text-red-300"
        : s === "DISABLED"
          ? "border-slate-500/30 bg-slate-500/10 text-slate-400"
          : "border-amber-500/30 bg-amber-500/10 text-amber-300"; // PENDING/INSTALLING/DELETING
  const label =
    s === "PENDING" ? "Setting up…" : s === "INSTALLING" ? "Installing…" : s === "DELETING" ? "Removing…" : status;
  return (
    <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 text-[11px] font-medium ${tone}`}>
      {(s === "PENDING" || s === "INSTALLING" || s === "DELETING") && (
        <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-current" />
      )}
      {label}
    </span>
  );
}

/** A copy-to-clipboard button (local to the cpanel bundle). */
export function Copy({ text, label }: { text: string; label?: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost px-2 py-1 text-xs"
      onClick={() =>
        void navigator.clipboard.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        })
      }
    >
      {copied ? "Copied ✓" : label ?? "Copy"}
    </button>
  );
}

/**
 * A "shown once" secret card — the generated password / credentials that will
 * never be retrievable again. Rendered after a create/install succeeds.
 */
export function SecretCard({
  title,
  rows,
  onDismiss,
}: {
  title: string;
  rows: { label: string; value: string; mono?: boolean }[];
  onDismiss: () => void;
}) {
  return (
    <div className="glass mt-4 border-brand-500/30 p-4">
      <div className="mb-3 flex items-center justify-between gap-3">
        <h4 className="text-sm font-semibold text-brand-200">{title}</h4>
        <button type="button" className="btn-ghost px-2 py-1 text-xs" onClick={onDismiss}>
          Dismiss
        </button>
      </div>
      <p className="mb-3 text-xs text-amber-300">
        Save these now — for your security they are shown only once and cannot be retrieved later.
      </p>
      <dl className="space-y-2">
        {rows.map((r) => (
          <div key={r.label} className="flex flex-wrap items-center justify-between gap-2">
            <dt className="text-xs text-slate-400">{r.label}</dt>
            <dd className="flex items-center gap-2">
              <code className="rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1 font-mono text-xs text-slate-100">
                {r.value}
              </code>
              <Copy text={r.value} />
            </dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

/** A centered empty state inside a card. */
export function EmptyState({ title, hint }: { title: string; hint: string }) {
  return (
    <div className="px-4 py-10 text-center">
      <p className="text-sm font-medium text-slate-300">{title}</p>
      <p className="mx-auto mt-1 max-w-md text-xs text-slate-500">{hint}</p>
    </div>
  );
}

/** Skeleton loading rows. */
export function LoadingRows({ rows = 3 }: { rows?: number }) {
  return (
    <div className="space-y-2 p-4">
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className="h-10 animate-pulse rounded-xl bg-white/[0.04]" />
      ))}
    </div>
  );
}

/** A card telling the customer the server must be running. */
export function NotRunning({ what }: { what: string }) {
  return (
    <div className="card py-12 text-center">
      <h2 className="font-semibold">{what} unavailable</h2>
      <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
        The control panel works only while your server is{" "}
        <span className="font-medium text-slate-200">running</span>. Start the server to continue.
      </p>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import {
  listWebsites,
  createWebsite,
  toggleWebsite,
  requestWebsiteSsl,
  deleteWebsite,
  pointWebsiteDns,
} from "@/lib/actions-websites";
import { PHP_VERSIONS, type WebsiteRow } from "@/lib/cpanel-types";
import { StatusPill, EmptyState, LoadingRows } from "./shared";
import { CloudflareConnect, CloudflareResultBanner } from "../CloudflareConnect";

export function WebsitesPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [sites, setSites] = useState<WebsiteRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [domain, setDomain] = useState("");
  const [php, setPhp] = useState<string>("8.3");
  const [formError, setFormError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  // DNS-pointing state (Cloudflare).
  const [serverIp, setServerIp] = useState<string | null>(null);
  const [cfConnected, setCfConnected] = useState(false);
  const [autoPoint, setAutoPoint] = useState(true);
  const [dnsNote, setDnsNote] = useState<{ tone: "ok" | "error"; text: string } | null>(null);

  const refresh = useCallback(async () => {
    const res = await listWebsites(serverId);
    if (res.ok) {
      setSites(res.websites);
      setServerIp(res.serverIp);
      setCfConnected(res.cloudflareConnected);
    } else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Poll while any site is transitional so status settles without a manual reload.
  useEffect(() => {
    if (!sites?.some((s) => ["PENDING", "DELETING"].includes(s.status))) return;
    const t = setInterval(() => void refresh(), 4000);
    return () => clearInterval(t);
  }, [sites, refresh]);

  const add = () =>
    start(async () => {
      setFormError(null);
      setDnsNote(null);
      const res = await createWebsite(serverId, domain, php === "static" ? null : php);
      if (!res.ok) {
        setFormError(res.error);
        return;
      }
      setDomain("");
      // Opt-in: create the A record for the new site in the customer's Cloudflare
      // zone right away, so SSL can be issued without a manual DNS detour.
      if (autoPoint && cfConnected) {
        const dns = await pointWebsiteDns(res.id);
        setDnsNote(dns.ok ? { tone: "ok", text: dns.message } : { tone: "error", text: dns.error });
      }
      await refresh();
    });

  const pointDns = (id: string) =>
    start(async () => {
      setDnsNote(null);
      const dns = await pointWebsiteDns(id);
      setDnsNote(dns.ok ? { tone: "ok", text: dns.message } : { tone: "error", text: dns.error });
      await refresh();
    });

  const act = (fn: () => Promise<{ ok: boolean; error?: string }>) =>
    start(async () => {
      setError(null);
      const res = await fn();
      if (!res.ok && res.error) setError(res.error);
      await refresh();
    });

  return (
    <div className="space-y-6">
      <CloudflareResultBanner />

      <div className="card">
        <h3 className="mb-1 font-semibold">Add a website</h3>
        <p className="mb-4 text-sm text-slate-400">
          Generates an nginx server block with a document root under{" "}
          <code className="font-mono text-xs text-brand-300">/var/www/&lt;domain&gt;</code> and installs the
          chosen PHP-FPM version if needed.
        </p>
        <div className="flex flex-wrap items-end gap-3">
          <div className="grow">
            <label className="label">Domain</label>
            <input
              className="input"
              placeholder="example.com or blog.example.com"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              disabled={pending || !running}
            />
          </div>
          <div>
            <label className="label">PHP version</label>
            <select className="input w-44" value={php} onChange={(e) => setPhp(e.target.value)} disabled={pending || !running}>
              {PHP_VERSIONS.map((v) => (
                <option key={v} value={v}>
                  PHP {v}
                </option>
              ))}
              <option value="static">Static (no PHP)</option>
            </select>
          </div>
          <button className="btn-primary" onClick={add} disabled={pending || !running || domain.trim().length < 3}>
            {pending ? "Working…" : "Add website"}
          </button>
        </div>
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to add websites.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}

        {/* --- Point DNS at this server (Cloudflare) ------------------------ */}
        <div className="mt-4 rounded-xl border border-sky-500/25 bg-sky-500/[0.05] p-3">
          <p className="text-sm font-semibold text-white">Point DNS to this server automatically</p>
          <p className="mt-1 text-xs text-slate-300">
            Adds an <span className="font-mono">A</span> record for the domain
            {serverIp ? (
              <>
                {" "}
                → <span className="font-mono text-slate-100">{serverIp}</span>
              </>
            ) : null}{" "}
            in your Cloudflare zone. We set it to{" "}
            <span className="font-medium text-slate-200">DNS-only (no orange cloud)</span> on purpose:
            Let&apos;s Encrypt has to reach this server directly to validate, so proxied records break
            one-click SSL. DNS changes can take a few minutes to reach everyone.
          </p>

          {dnsNote && (
            <div
              className={`mt-2 rounded-lg border px-3 py-2 text-xs ${
                dnsNote.tone === "ok"
                  ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
                  : "border-red-500/30 bg-red-500/10 text-red-400"
              }`}
            >
              {dnsNote.text}
            </div>
          )}

          <div className="mt-2">
            <CloudflareConnect
              intent="settings"
              next={`/dashboard/servers/${serverId}`}
              connectedHint={cfConnected}
              onConnected={() => {
                setCfConnected(true);
                void refresh();
              }}
              what="bring you straight back here"
            >
              <label className="flex cursor-pointer items-center gap-2 text-xs text-slate-300">
                <input
                  type="checkbox"
                  className="accent-brand-500"
                  checked={autoPoint}
                  onChange={(e) => setAutoPoint(e.target.checked)}
                  disabled={pending}
                />
                Point DNS at this server when I add a website (you can also do it per site below)
              </label>
            </CloudflareConnect>
          </div>
        </div>
      </div>

