                        </button>
                        {!s.appSlug && (
                          <button
                            className="btn-danger px-2.5 py-1 text-xs"
                            disabled={pending || busy}
                            onClick={() => {
                              if (window.confirm(`Delete ${s.domain}? The nginx site and its document root are removed.`))
                                act(() => deleteWebsite(s.id));
                            }}
                          >
                            Delete
