"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { listDatabases, createDatabase, deleteDatabase } from "@/lib/actions-databases";
import { DB_ENGINES, DB_ENGINE_LABEL, type DbEngine, type DatabaseRow } from "@/lib/cpanel-types";
import { StatusPill, EmptyState, LoadingRows, SecretCard } from "./shared";

export function DatabasesPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [rows, setRows] = useState<DatabaseRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [engine, setEngine] = useState<DbEngine>("mysql");
  const [name, setName] = useState("");
  const [dbUser, setDbUser] = useState("");
  const [formError, setFormError] = useState<string | null>(null);
  const [secret, setSecret] = useState<{ name: string; dbUser: string; password: string; engine: string } | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await listDatabases(serverId);
    if (res.ok) setRows(res.databases);
    else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!rows?.some((r) => ["PENDING", "DELETING"].includes(r.status))) return;
    const t = setInterval(() => void refresh(), 4000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  const create = () =>
    start(async () => {
      setFormError(null);
      const res = await createDatabase(serverId, engine, name, dbUser);
      if (!res.ok) setFormError(res.error);
      else {
        setSecret({ name: res.name, dbUser: res.dbUser, password: res.password, engine });
        setName("");
        setDbUser("");
        await refresh();
      }
    });

  const remove = (r: DatabaseRow) =>
    start(async () => {
      setError(null);
      const res = await deleteDatabase(r.id);
      if (!res.ok) setError(res.error);
      await refresh();
    });

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">Create a database</h3>
        <p className="mb-4 text-sm text-slate-400">
          Provisions a database and an owner user on your server. The engine is installed automatically on
          first use. The generated password is shown once.
        </p>
        <div className="grid gap-3 sm:grid-cols-2 md:grid-cols-4">
          <div>
            <label className="label">Engine</label>
            <select className="input" value={engine} onChange={(e) => setEngine(e.target.value as DbEngine)} disabled={pending || !running}>
              {DB_ENGINES.map((e) => (
                <option key={e} value={e}>
                  {DB_ENGINE_LABEL[e]}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="label">Database name</label>
            <input className="input" placeholder="app_prod" value={name} onChange={(e) => setName(e.target.value)} disabled={pending || !running} maxLength={32} />
          </div>
          <div>
            <label className="label">Database user</label>
            <input className="input" placeholder="app_user" value={dbUser} onChange={(e) => setDbUser(e.target.value)} disabled={pending || !running} maxLength={32} />
          </div>
          <div className="flex items-end">
            <button className="btn-primary w-full" onClick={create} disabled={pending || !running || !name.trim() || !dbUser.trim()}>
              {pending ? "Working…" : "Create"}
            </button>
          </div>
        </div>
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to create databases.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
        {secret && (
          <SecretCard
            title={`${DB_ENGINE_LABEL[secret.engine as DbEngine]} database created`}
            rows={[
              { label: "Database", value: secret.name, mono: true },
              { label: "User", value: secret.dbUser, mono: true },
              { label: "Password", value: secret.password, mono: true },
              { label: "Host", value: "localhost", mono: true },
            ]}
            onDismiss={() => setSecret(null)}
          />
        )}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Databases</p>
        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
        {rows === null ? (
          <LoadingRows />
        ) : rows.length === 0 ? (
          <EmptyState title="No databases yet" hint="Create your first database above — MySQL/MariaDB or PostgreSQL." />
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th>Engine</th>
                <th>User</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => (
                <tr key={r.id}>
                  <td className="font-mono text-xs text-slate-100">{r.name}</td>
                  <td className="text-slate-400">{DB_ENGINE_LABEL[r.engine as DbEngine] ?? r.engine}</td>
                  <td className="font-mono text-xs text-slate-400">{r.dbUser}</td>
                  <td>
                    <StatusPill status={r.status} />
                    {r.error && <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={r.error}>{r.error}</div>}
                  </td>
                  <td>
                    <div className="flex justify-end">
                      <button
                        className="btn-danger px-2.5 py-1 text-xs"
                        disabled={pending || ["PENDING", "DELETING"].includes(r.status)}
                        onClick={() => {
                          if (window.confirm(`Delete database "${r.name}" and user "${r.dbUser}"? This cannot be undone.`))
                            remove(r);
                        }}
                      >
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { listApps, installApp, removeApp } from "@/lib/actions-apps";
import { APP_CATALOG, appBySlug, type AppRow } from "@/lib/cpanel-types";
import { StatusPill, EmptyState, LoadingRows, SecretCard } from "./shared";

export function AppsPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [apps, setApps] = useState<AppRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [domain, setDomain] = useState("");
  const [adminUser, setAdminUser] = useState("admin");
  const [formError, setFormError] = useState<string | null>(null);
  const [secret, setSecret] = useState<{ rows: { label: string; value: string }[]; name: string } | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await listApps(serverId);
    if (res.ok) setApps(res.apps);
    else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!apps?.some((a) => ["PENDING", "INSTALLING"].includes(a.status))) return;
    const t = setInterval(() => void refresh(), 5000);
    return () => clearInterval(t);
  }, [apps, refresh]);

  const install = () =>
    start(async () => {
      if (!selected) return;
      setFormError(null);
      const res = await installApp(serverId, selected, domain, adminUser);
      if (!res.ok) setFormError(res.error);
      else {
        const rows = [
          { label: "URL", value: `http://${res.domain}/` },
          { label: "Admin user", value: res.adminUser },
          { label: "Admin password", value: res.adminPassword },
        ];
        if (res.dbName) {
          rows.push({ label: "Database", value: res.dbName });
          rows.push({ label: "DB user", value: res.dbUser });
          rows.push({ label: "DB password", value: res.dbPassword });
        }
        setSecret({ rows, name: appBySlug(selected)?.name ?? "App" });
        setSelected(null);
        setDomain("");
        await refresh();
      }
    });

  const remove = (a: AppRow) =>
    start(async () => {
      setError(null);
      const res = await removeApp(a.id);
      if (!res.ok) setError(res.error);
      await refresh();
    });

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">One-click apps</h3>
        <p className="mb-4 text-sm text-slate-400">
          Provisions a website (vhost + docroot), a database, and the application in one step. Point the
          domain&apos;s DNS at this server first. Admin and database passwords are shown once.
        </p>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {APP_CATALOG.map((app) => {
            const active = selected === app.slug;
            return (
              <button
                key={app.slug}
                type="button"
                disabled={!running}
                onClick={() => setSelected(active ? null : app.slug)}
                className={`card-hover flex items-start gap-3 rounded-2xl border p-4 text-left transition-all disabled:opacity-50 ${
                  active ? "border-brand-500/60 bg-brand-500/[0.06]" : "border-white/[0.06] bg-navy-900/60"
                }`}
              >
                <span className="text-2xl">{app.emoji}</span>
                <span>
                  <span className="block text-sm font-semibold text-slate-100">{app.name}</span>
                  <span className="mt-0.5 block text-xs text-slate-400">{app.description}</span>
                </span>
              </button>
            );
          })}
        </div>

        {selected && (
          <div className="mt-4 border-t border-white/[0.06] pt-4">
            <div className="flex flex-wrap items-end gap-3">
              <div className="grow">
                <label className="label">Domain</label>
                <input className="input" placeholder="blog.example.com" value={domain} onChange={(e) => setDomain(e.target.value)} disabled={pending} />
              </div>
              <div>
                <label className="label">Admin user</label>
                <input className="input w-40" value={adminUser} onChange={(e) => setAdminUser(e.target.value)} disabled={pending} maxLength={32} />
              </div>
              <button className="btn-primary" onClick={install} disabled={pending || domain.trim().length < 3}>
                {pending ? "Installing…" : `Install ${appBySlug(selected)?.name}`}
              </button>
            </div>
          </div>
        )}
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to install apps.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
        {secret && (
          <SecretCard title={`${secret.name} installed`} rows={secret.rows} onDismiss={() => setSecret(null)} />
        )}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Installed apps</p>
        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
        {apps === null ? (
          <LoadingRows />
        ) : apps.length === 0 ? (
          <EmptyState title="No apps installed" hint="Pick an application above to deploy it in one click." />
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>App</th>
                <th>Domain</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {apps.map((a) => (
                <tr key={a.id}>
                  <td>
                    <span className="mr-1.5">{appBySlug(a.appSlug)?.emoji}</span>
                    <span className="font-medium text-slate-100">{appBySlug(a.appSlug)?.name ?? a.appSlug}</span>
                  </td>
                  <td>
                    {a.url ? (
                      <a href={a.url} target="_blank" rel="noreferrer" className="text-brand-300 hover:underline">
                        {a.domain}
                      </a>
                    ) : (
                      <span className="text-slate-400">{a.domain}</span>
                    )}
                  </td>
                  <td>
                    <StatusPill status={a.status} />
                    {a.error && <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={a.error}>{a.error}</div>}
                  </td>
                  <td>
                    <div className="flex justify-end">
                      <button
                        className="btn-danger px-2.5 py-1 text-xs"
                        disabled={pending || a.status === "INSTALLING"}
                        onClick={() => {
                          if (window.confirm(`Remove ${appBySlug(a.appSlug)?.name ?? a.appSlug} on ${a.domain}? Its site and database are deleted.`))
                            remove(a);
                        }}
                      >
                        Remove
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

