import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { encryptSecret } from "./crypto-box";
import { DOMAIN_RE, generateStrongPassword } from "./ssh-exec";
import { appBySlug, type AppRow } from "./cpanel-types";

type InstallResult =
  | {
      ok: true;
      id: string;
      domain: string;
      adminUser: string;
      adminPassword: string;
      dbName: string;
      dbUser: string;
      dbPassword: string;
    }
  | { ok: false; error: string };
type Result = { ok: true } | { ok: false; error: string };

const EXCLUSIVE_JOBS = [
  "PROVISION",
  "REINSTALL",
  "DELETE",
  "RESIZE",
  "SUSPEND",
  "UNSUSPEND",
  "SNAPSHOT_ROLLBACK",
  "BACKUP_RESTORE",
  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
  // control-panel operations out of the way while the root filesystem is resized.
  "DISK_EXPAND",
] as const;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, status: true, hostname: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function ownedApp(id: string) {
  const user = await requireUser();
  const app = await db.appInstall.findUnique({ where: { id } });
  if (!app) throw new Error("Not found");
  if (app.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, app };
}

function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`cpanel:app:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

async function lifecycleBusy(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
  });
  return n > 0;
}

function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  return msg.slice(0, 300);
}

function rowOut(a: {
  id: string;
  appSlug: string;
  domain: string;
  url: string | null;
  adminUser: string | null;
  status: string;
  error: string | null;
  createdAt: Date;
}): AppRow {
  return {
    id: a.id,
    appSlug: a.appSlug,
    domain: a.domain,
    url: a.url,
    adminUser: a.adminUser,
    status: a.status,
    error: a.error,
    createdAt: a.createdAt.toISOString(),
  };
}

/** Derive a safe DB identifier (letters/digits/underscore, <=32) from a domain. */
function dbIdentFromDomain(domain: string, prefix: string): string {
  const base = domain.replace(/[^a-z0-9]/gi, "_").slice(0, 20);
  const suffix = Math.random().toString(36).slice(2, 6);
  return `${prefix}_${base}_${suffix}`.replace(/_+/g, "_").slice(0, 32);
}

// ---------------------------------------------------------------------------

export async function listApps(
  serverId: string
): Promise<{ ok: true; apps: AppRow[] } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const rows = await db.appInstall.findMany({
      where: { serverId: server.id },
      orderBy: { createdAt: "desc" },
    });
    return { ok: true, apps: rows.map(rowOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function installApp(
  serverId: string,
  appSlug: string,
  domainInput: string,
  adminUserInput?: string
): Promise<InstallResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "install", 6);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to install an app." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };

    const app = appBySlug(appSlug);
    if (!app) return { ok: false, error: "Unknown application." };

    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
    if (!DOMAIN_RE.test(domain))
      return { ok: false, error: "Enter a valid domain (e.g. blog.example.com) pointed at this server." };

    const adminUser = (String(adminUserInput ?? "admin").replace(/[^a-z0-9_]/gi, "") || "admin").slice(0, 32);

    // Domain must be free of an existing website on this server.
    const dupSite = await db.website.findFirst({ where: { serverId: server.id, domain } });
    if (dupSite) return { ok: false, error: `A website for ${domain} already exists on this server.` };

    const adminPassword = generateStrongPassword(18);
    const dbName = app.engine ? dbIdentFromDomain(domain, "db") : "";
    const dbUser = app.engine ? dbIdentFromDomain(domain, "u") : "";
    const dbPassword = app.engine ? generateStrongPassword(20) : "";

    // Create the primitives + the install record in one transaction.
    const { appRow } = await db.$transaction(async (tx) => {
      const website = await tx.website.create({
        data: {
          userId: user.id,
          serverId: server.id,
          domain,
          docRoot: `/var/www/${domain}`,
          phpVersion: app.php,
          isSubdomain: domain.split(".").length > 2,
          appSlug: app.slug,
          status: "PENDING",
        },
      });
      let database: { id: string } | null = null;
      if (app.engine) {
        database = await tx.vpsDatabase.create({
          data: {
            userId: user.id,
            serverId: server.id,
            engine: app.engine,
            name: dbName,
            dbUser,
            passwordEnc: encryptSecret(dbPassword),
            status: "PENDING",
          },
        });
      }
      const appRow = await tx.appInstall.create({
        data: {
          userId: user.id,
          serverId: server.id,
          appSlug: app.slug,
          domain,
          websiteId: website.id,
          databaseId: database?.id ?? null,
          adminUser,
          adminPassEnc: encryptSecret(adminPassword),
          status: "PENDING",
        },
      });
      return { appRow };
    });

    await db.job.create({ data: { type: "APP_INSTALL", serverId: server.id, payload: { appId: appRow.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.app.install", detail: `${app.slug} → ${domain} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    // Credentials returned ONCE.
    return {
      ok: true,
      id: appRow.id,
      domain,
      adminUser,
      adminPassword,
      dbName,
      dbUser,
      dbPassword,
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function removeApp(id: string): Promise<Result> {
  try {
    const { user, app } = await ownedApp(id);
    const limited = throttle(user.id, "remove", 10);
    if (limited) return { ok: false, error: limited };
    if (app.status === "INSTALLING") return { ok: false, error: "This app is still installing — try again shortly." };

    // Tear down the provisioned site + database via their own worker jobs, then
    // drop the AppInstall record. The site/db rows carry the SSH cleanup.
    if (app.websiteId) {
      const site = await db.website.findUnique({ where: { id: app.websiteId } });
      if (site) {
        await db.website.update({ where: { id: site.id }, data: { status: "DELETING", appSlug: null } });
        await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: app.serverId, payload: { websiteId: site.id } } });
      }
    }
    if (app.databaseId) {
      const database = await db.vpsDatabase.findUnique({ where: { id: app.databaseId } });
      if (database) {
        await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "DELETING" } });
        await db.job.create({ data: { type: "DB_DELETE", serverId: app.serverId, payload: { databaseId: database.id } } });
      }
    }
    await db.appInstall.delete({ where: { id } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.app.remove", detail: `${app.appSlug} (${app.domain})` },
    });
    revalidatePath(`/dashboard/servers/${app.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

