export async function listCronJobs(
  serverId: string
): Promise<{ ok: true; cron: CronRow[] } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const rows = await db.cronJob.findMany({
      where: { serverId: server.id },
      orderBy: { createdAt: "desc" },
    });
    return { ok: true, cron: rows.map(rowOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createCronJob(
  serverId: string,
  schedule: string,
  command: string,
  comment?: string
): Promise<CreateResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "create", 20);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to manage cron jobs." };

    let normSchedule: string;
    let normCommand: string;
    try {
      normSchedule = assertCronSchedule(schedule);
      normCommand = validateCommand(command);
    } catch (e) {
      return { ok: false, error: e instanceof Error ? e.message : "Invalid cron entry." };
    }
    const note = comment ? String(comment).replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, 80) : null;

    const count = await db.cronJob.count({ where: { serverId: server.id } });
    if (count >= 50) return { ok: false, error: "Cron job limit reached (50 per server)." };

    const row = await db.cronJob.create({
      data: {
        userId: user.id,
        serverId: server.id,
        schedule: normSchedule,
        command: normCommand,
        comment: note,
        enabled: true,
        status: "PENDING",
      },
    });
    await db.job.create({ data: { type: "CRON_SYNC", serverId: server.id, payload: {} } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.cron.create", detail: `${normSchedule} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true, id: row.id };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function updateCronJob(
  id: string,
  schedule: string,
  command: string,
  comment?: string
): Promise<Result> {
  try {
    const { user, cron } = await ownedCron(id);
    const limited = throttle(user.id, "update", 20);
    if (limited) return { ok: false, error: limited };
    let normSchedule: string;
    let normCommand: string;
    try {
      normSchedule = assertCronSchedule(schedule);
      normCommand = validateCommand(command);
    } catch (e) {
      return { ok: false, error: e instanceof Error ? e.message : "Invalid cron entry." };
    }
    const note = comment ? String(comment).replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, 80) : null;
    await db.cronJob.update({
      where: { id },
      data: { schedule: normSchedule, command: normCommand, comment: note, status: "PENDING" },
    });
    await db.job.create({ data: { type: "CRON_SYNC", serverId: cron.serverId, payload: {} } });
    revalidatePath(`/dashboard/servers/${cron.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function toggleCronJob(id: string): Promise<Result> {
  try {
    const { user, cron } = await ownedCron(id);
    const limited = throttle(user.id, "toggle", 30);
    if (limited) return { ok: false, error: limited };
    await db.cronJob.update({ where: { id }, data: { enabled: !cron.enabled, status: "PENDING" } });
    await db.job.create({ data: { type: "CRON_SYNC", serverId: cron.serverId, payload: {} } });
    revalidatePath(`/dashboard/servers/${cron.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function deleteCronJob(id: string): Promise<Result> {
  try {
    const { user, cron } = await ownedCron(id);
    const limited = throttle(user.id, "delete", 30);
    if (limited) return { ok: false, error: limited };
    // Mark DELETING then re-sync — the worker rebuilds the crontab block from the
    // remaining rows and removes the DELETING ones.
    await db.cronJob.update({ where: { id }, data: { status: "DELETING" } });
    await db.job.create({ data: { type: "CRON_SYNC", serverId: cron.serverId, payload: {} } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.cron.delete", detail: cron.schedule },
    });
    revalidatePath(`/dashboard/servers/${cron.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

