export async function serviceAction(
  serverId: string,
  unit: string,
  action: string
): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "svc-action", 20);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to control services." };
    if (!COMMON_SERVICES.some((s) => s.unit === unit))
      return { ok: false, error: "Unsupported service." };
    if (!(SERVICE_ACTIONS as readonly string[]).includes(action))
      return { ok: false, error: "Unsupported action." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };

    await db.job.create({
      data: { type: "SERVICE_ACTION", serverId: server.id, payload: { unit, action } },
    });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.service", detail: `${action} ${unit} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

