import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import {
  withServerSsh,
  exec,
  execInput,
  assertDomain,
  assertPhp,
  assertPath,
  shellQuote,
  pkgInstallPrefix,
  SETUP_TIMEOUT_MS,
  INSTALL_TIMEOUT_MS,
  QUICK_TIMEOUT_MS,
} from "../lib/ssh-exec";
import type { Job } from "@prisma/client";

/**
 * Control-panel WEBSITE_* handlers.
 *
 * Registered in worker/index.ts:
 *   WEBSITE_CREATE: websiteCreate,
 *   WEBSITE_DELETE: websiteDelete,
 *   WEBSITE_TOGGLE: websiteToggle,
 *   WEBSITE_SSL:    websiteSsl,
 *
 * Ownership + validation happen at enqueue time (lib/actions-websites.ts); these
 * trust `payload.websiteId` but STILL re-validate every value against the strict
 * allowlist in lib/ssh-exec before it can reach a shell.
 *
 * SANDBOX (staging): no SSH — statuses flip with synthetic success, exactly like
 * every other worker feature. On prod the real nginx/php/certbot work runs only
 * when ENABLE_REAL_CPANEL === "1" (belt-and-suspenders, mirroring worker/ssl.ts);
 * otherwise it also takes the simulated-success branch so a fresh prod box can't
 * be mutated until the operator explicitly enables it.
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/web] notify failed", e);
  }
}

async function loadSite(job: Job) {
  const p = (job.payload ?? {}) as { websiteId?: string };
  if (!p.websiteId) throw new Error("website job: missing websiteId");
  const site = await db.website.findUnique({ where: { id: p.websiteId } });
  if (!site) throw new Error(`Website ${p.websiteId} not found`);
  return site;
}

/** Load exactly the SSH fields for a server (mirrors lib/sftp usage). */
export async function sshServer(serverId: string): Promise<SftpServer> {
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!s) throw new Error(`Server ${serverId} not found`);
  return s as SftpServer;
}

/** Render an nginx server block. All values are allowlist-validated by callers. */
export function nginxVhost(domain: string, docRoot: string, phpVersion: string | null): string {
  const phpBlock = phpVersion
    ? `
    location ~ \\.php$ {
        include snippets/fastcgi-php.conf;
        fastcgi_pass unix:/run/php/php${phpVersion}-fpm.sock;
    }
`
    : "";
  return `# Managed by Nxeon control panel — do not edit by hand.
server {
    listen 80;
    listen [::]:80;
    server_name ${domain};
    root ${docRoot};
    index index.php index.html index.htm;

    location / {
        try_files $uri $uri/ /index.php?$query_string;
    }
${phpBlock}
    access_log /var/log/nginx/${domain}.access.log;
    error_log /var/log/nginx/${domain}.error.log;
}
`;
}

export async function ensureNginx(conn: import("ssh2").Client): Promise<void> {
  const have = await exec(conn, "command -v nginx >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
  if (have.stdout.trim() !== "yes") {
    const prefix = await pkgInstallPrefix(conn);
    const inst = await exec(conn, `${prefix} nginx`, INSTALL_TIMEOUT_MS);
    if (inst.code !== 0) throw new Error(`nginx install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
  }
  // Ensure the sites-available/enabled layout exists (Debian/Ubuntu default).
  await exec(conn, "mkdir -p /etc/nginx/sites-available /etc/nginx/sites-enabled", SETUP_TIMEOUT_MS);
}

export async function ensurePhpFpm(conn: import("ssh2").Client, phpVersion: string): Promise<void> {
  assertPhp(phpVersion);
  const svc = `php${phpVersion}-fpm`;
  const have = await exec(conn, `systemctl status ${shellQuote(svc)} >/dev/null 2>&1 && echo yes || echo no`, QUICK_TIMEOUT_MS);
  if (have.stdout.trim() === "yes") return;
  const prefix = await pkgInstallPrefix(conn);
  // php{ver}-fpm + the common extensions apps need.
  const inst = await exec(
    conn,
    `${prefix} php${phpVersion}-fpm php${phpVersion}-mysql php${phpVersion}-cli php${phpVersion}-curl php${phpVersion}-gd php${phpVersion}-mbstring php${phpVersion}-xml`,
    INSTALL_TIMEOUT_MS
  );
  if (inst.code !== 0) throw new Error(`php-fpm install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
  await exec(conn, `systemctl enable --now ${shellQuote(svc)}`, SETUP_TIMEOUT_MS);
}

export async function reloadNginx(conn: import("ssh2").Client): Promise<void> {
  const test = await exec(conn, "nginx -t", SETUP_TIMEOUT_MS);
  if (test.code !== 0) throw new Error(`nginx config test failed: ${(test.stderr || test.stdout).trim().slice(0, 200)}`);
  await exec(conn, "systemctl reload nginx || systemctl restart nginx", SETUP_TIMEOUT_MS);
}

// ---------------------------------------------------------------------------

export async function websiteCreate(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      assertPath(site.docRoot);
      if (site.phpVersion) assertPhp(site.phpVersion);
      const server = await sshServer(site.serverId);
      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
      await withServerSsh(server, async (conn) => {
        await ensureNginx(conn);
        if (site.phpVersion) await ensurePhpFpm(conn, site.phpVersion);
        // Docroot + a friendly placeholder index.
        await exec(conn, `mkdir -p ${shellQuote(site.docRoot)} && chown -R www-data:www-data ${shellQuote(site.docRoot)} 2>/dev/null || true`, SETUP_TIMEOUT_MS);
        await execInput(
          conn,
          `cat > ${shellQuote(site.docRoot + "/index.html")}`,
          `<!doctype html><meta charset="utf-8"><title>${site.domain}</title><h1>${site.domain}</h1><p>Your Nxeon-hosted site is live.</p>\n`,
          SETUP_TIMEOUT_MS
        );
        // Write the vhost via STDIN (never as an argv token), enable, reload.
        await execInput(conn, `cat > ${shellQuote(conf)}`, nginxVhost(site.domain, site.docRoot, site.phpVersion), SETUP_TIMEOUT_MS);
        if (site.enabled) {
          await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
        }
        await reloadNginx(conn);
      });
    }
    await db.website.update({ where: { id: site.id }, data: { status: "ACTIVE", error: null } });
    await notify(
      site.userId,
      `Website ${site.domain} is live`,
      REAL ? "Your nginx site is configured and serving." : "Your website was created (sandbox — no real VM was touched).",
      `/dashboard/servers/${site.serverId}?tab=control panel`
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
    await notify(site.userId, `Website ${site.domain} failed`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
  }
}

export async function websiteToggle(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      const server = await sshServer(site.serverId);
      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
      await withServerSsh(server, async (conn) => {
        if (site.enabled) await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
        else await exec(conn, `rm -f ${shellQuote(link)}`, SETUP_TIMEOUT_MS);
        await reloadNginx(conn);
      });
    }
    await db.website.update({ where: { id: site.id }, data: { status: site.enabled ? "ACTIVE" : "DISABLED", error: null } });
  } catch (e: any) {
    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
  }
}

export async function websiteSsl(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      const server = await sshServer(site.serverId);
      const email = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
      await withServerSsh(server, async (conn) => {
        const have = await exec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
        if (have.stdout.trim() !== "yes") {
          const prefix = await pkgInstallPrefix(conn);
          const inst = await exec(conn, `${prefix} certbot python3-certbot-nginx`, INSTALL_TIMEOUT_MS);
          if (inst.code !== 0) throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 200)}`);
        }
        // Use the nginx installer so the vhost is upgraded to 443 in place.
        const run = await exec(
          conn,
          `certbot --nginx -n --agree-tos -m ${shellQuote(email)} -d ${shellQuote(site.domain)} --redirect`,
          INSTALL_TIMEOUT_MS
        );
        const combined = `${run.stdout}\n${run.stderr}`;
        const ok = run.code === 0 && /Congratulations|Successfully|not yet due for renewal|Deploying certificate/i.test(combined);
        if (!ok) throw new Error(`certbot failed: ${combined.trim().slice(0, 300)}`);
      });
    }
    await db.website.update({ where: { id: site.id }, data: { ssl: true, error: null } });
    await notify(
      site.userId,
      `SSL enabled for ${site.domain}`,
      REAL ? "A Let's Encrypt certificate is installed and HTTP redirects to HTTPS." : "SSL enabled (sandbox).",
      `/dashboard/servers/${site.serverId}?tab=control panel`
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    await db.website.update({ where: { id: site.id }, data: { error: reason } });
    await notify(site.userId, `SSL failed for ${site.domain}`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
  }
}

export async function websiteDelete(job: Job): Promise<void> {
  const site = await loadSite(job);
  try {
    if (REAL) {
      assertDomain(site.domain);
      assertPath(site.docRoot);
      const server = await sshServer(site.serverId);
      const conf = `/etc/nginx/sites-available/${site.domain}.conf`;
      const link = `/etc/nginx/sites-enabled/${site.domain}.conf`;
      await withServerSsh(server, async (conn) => {
        await exec(conn, `rm -f ${shellQuote(link)} ${shellQuote(conf)}`, SETUP_TIMEOUT_MS);
        // Remove the docroot ONLY within /var/www (validated path); leave data
        // elsewhere untouched.
        if (site.docRoot.startsWith("/var/www/")) {
          await exec(conn, `rm -rf ${shellQuote(site.docRoot)}`, SETUP_TIMEOUT_MS);
        }
        await reloadNginx(conn).catch(() => {});
      });
    }
    await db.website.delete({ where: { id: site.id } });
  } catch (e: any) {
    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 400) } });
  }
}

"use server";

/**
 * Control panel — Websites & PHP.
 *
 * Add a website (nginx server block + docroot under /var/www/<domain>), pick a
 * PHP-FPM version, enable/disable, one-click Let's Encrypt SSL, and subdomains.
 * List/edit/delete. Every op is ownership-checked + rate-limited and respects
 * the "no panel work while a lifecycle job is in flight / server not running"
 * invariant. The real SSH work runs in worker/websites.ts (sandbox-gated); the
 * lists here are served straight from the Website table.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { DOMAIN_RE, PHP_VERSION_RE } from "./ssh-exec";
import { PHP_VERSIONS, type WebsiteRow } from "./cpanel-types";
import { pointHostnameToIp } from "./cloudflare-point";
import { readStoredCloudflare } from "./cloudflare-oauth";

type Result = { ok: true } | { ok: false; error: string };
type CreateResult = { ok: true; id: string } | { ok: false; error: string };
type PointResult = { ok: true; message: string } | { ok: false; error: string };

/** Job types that must not overlap with panel work (lifecycle / destructive). */
const EXCLUSIVE_JOBS = [
  "PROVISION",
  "REINSTALL",
  "DELETE",
  "RESIZE",
  "SUSPEND",
  "UNSUSPEND",
  "SNAPSHOT_ROLLBACK",
  "BACKUP_RESTORE",
  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
  // control-panel operations out of the way while the root filesystem is resized.
  "DISK_EXPAND",
] as const;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, status: true, hostname: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function ownedWebsite(id: string) {
  const user = await requireUser();
  const site = await db.website.findUnique({
    where: { id },
    include: { server: { select: { id: true, userId: true, status: true } } },
  });
  if (!site) throw new Error("Not found");
  if (site.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, site };
}

function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`cpanel:web:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

/** Reject if a lifecycle/destructive job is queued or running on the server. */
async function lifecycleBusy(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
  });
  return n > 0;
}

function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  return msg.slice(0, 300);
}

function rowOut(w: {
  id: string;
  domain: string;
  docRoot: string;
  phpVersion: string | null;
  ssl: boolean;
  enabled: boolean;
  isSubdomain: boolean;
  parentDomain: string | null;
  appSlug: string | null;
  status: string;
  error: string | null;
  createdAt: Date;
}): WebsiteRow {
  return {
    id: w.id,
    domain: w.domain,
    docRoot: w.docRoot,
    phpVersion: w.phpVersion,
    ssl: w.ssl,
    enabled: w.enabled,
    isSubdomain: w.isSubdomain,
    parentDomain: w.parentDomain,
    appSlug: w.appSlug,
    status: w.status,
    error: w.error,
    createdAt: w.createdAt.toISOString(),
  };
}

// ---------------------------------------------------------------------------

export async function listWebsites(
  serverId: string
): Promise<
  | { ok: true; websites: WebsiteRow[]; serverIp: string | null; cloudflareConnected: boolean }
  | { ok: false; error: string }
> {
  try {
    const { user, server } = await ownedServer(serverId);
    const sites = await db.website.findMany({
      where: { serverId: server.id },
      orderBy: { createdAt: "desc" },
    });
    return {
      ok: true,
      websites: sites.map(rowOut),
      // Both feed the "point DNS at this server" control in the panel.
      serverIp: await publicIpOf(server.id),
      cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/**
 * The address a customer's domain should resolve to for this server: its
 * dedicated failover IP when one is attached, otherwise the server's own public
 * IPv4. Null while the server is still being provisioned.
 */
async function publicIpOf(serverId: string): Promise<string | null> {
  const row = await db.server.findUnique({
    where: { id: serverId },
    select: { ipAddress: true, dedicatedIp: { select: { address: true } } },
  });
  return row?.dedicatedIp?.address ?? row?.ipAddress ?? null;
}

/**
 * Point a website's hostname at the server it lives on, by upserting an A record
 * in the customer's Cloudflare zone.
 *
 * Guards: requireUser + website ownership (via ownedWebsite), rate-limited like
 * its neighbours, and the hostname is taken from OUR Website row — never from
 * client input — then re-validated inside pointHostnameToIp.
 *
 * The record is written PROXIED = FALSE (DNS-only). That is deliberate: the name
 * must resolve to this server so Let's Encrypt's HTTP-01 challenge reaches
 * certbot on the box. Behind Cloudflare's proxy the challenge is answered at
 * their edge and SSL issuance fails.
 */
export async function pointWebsiteDns(id: string): Promise<PointResult> {
  try {
    const { user, site } = await ownedWebsite(id);
    const limited = throttle(user.id, "dns", 12);
    if (limited) return { ok: false, error: limited };

    const ip = await publicIpOf(site.serverId);
    if (!ip) {
      return {
        ok: false,
        error: "This server doesn't have a public IP yet — try again once it has finished provisioning.",
      };
    }

    const res = await pointHostnameToIp({
      user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
      hostname: site.domain,
      ip,
    });
    if (!res.ok) return { ok: false, error: res.error };

    await db.auditLog.create({
      data: {
        userId: user.id,
        action: "cpanel.website.dns",
        detail: `${site.domain} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
      },
    });
    revalidatePath(`/dashboard/servers/${site.serverId}`);

    return {
      ok: true,
      message: res.simulated
        ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). No record was sent to Cloudflare.`
        : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). DNS changes can take a few minutes to reach everyone.`,
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createWebsite(
  serverId: string,
  domainInput: string,
  phpVersion: string | null,
  parentDomain?: string
): Promise<CreateResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "create", 10);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to add a website." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };

    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
    if (!DOMAIN_RE.test(domain))
      return { ok: false, error: "Enter a valid domain (e.g. example.com or blog.example.com)." };

    const php = phpVersion ? String(phpVersion).trim() : null;
    if (php && (!PHP_VERSION_RE.test(php) || !(PHP_VERSIONS as readonly string[]).includes(php)))
      return { ok: false, error: "Choose a supported PHP version." };

    const isSubdomain = !!parentDomain;
    const parent = parentDomain ? String(parentDomain).toLowerCase().trim() : null;
    if (parent && !DOMAIN_RE.test(parent)) return { ok: false, error: "Invalid parent domain." };

    const existing = await db.website.findFirst({ where: { serverId: server.id, domain } });
    if (existing) return { ok: false, error: `A website for ${domain} already exists on this server.` };

    const count = await db.website.count({ where: { serverId: server.id } });
    if (count >= 50) return { ok: false, error: "Website limit reached (50 per server)." };

    const docRoot = `/var/www/${domain}`;
    const site = await db.website.create({
      data: {
        userId: user.id,
        serverId: server.id,
        domain,
        docRoot,
        phpVersion: php,
        isSubdomain,
        parentDomain: parent,
        status: "PENDING",
      },
    });
    await db.job.create({ data: { type: "WEBSITE_CREATE", serverId: server.id, payload: { websiteId: site.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.website.create", detail: `${domain} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true, id: site.id };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function toggleWebsite(id: string): Promise<Result> {
  try {
    const { user, site } = await ownedWebsite(id);
    const limited = throttle(user.id, "toggle", 20);
    if (limited) return { ok: false, error: limited };
    if (site.status === "PENDING" || site.status === "DELETING")
      return { ok: false, error: "This website is still being set up." };
    await db.website.update({ where: { id }, data: { enabled: !site.enabled, status: "PENDING" } });
    await db.job.create({ data: { type: "WEBSITE_TOGGLE", serverId: site.serverId, payload: { websiteId: id } } });
    revalidatePath(`/dashboard/servers/${site.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function requestWebsiteSsl(id: string): Promise<Result> {
  try {
    const { user, site } = await ownedWebsite(id);
    const limited = throttle(user.id, "ssl", 10);
    if (limited) return { ok: false, error: limited };
    if (site.status !== "ACTIVE") return { ok: false, error: "The website must be active before enabling SSL." };
    if (site.ssl) return { ok: false, error: "SSL is already enabled for this website." };
    await db.job.create({ data: { type: "WEBSITE_SSL", serverId: site.serverId, payload: { websiteId: id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.website.ssl", detail: site.domain },
    });
    revalidatePath(`/dashboard/servers/${site.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function deleteWebsite(id: string): Promise<Result> {
  try {
    const { user, site } = await ownedWebsite(id);
    const limited = throttle(user.id, "delete", 15);
    if (limited) return { ok: false, error: limited };
    if (site.appSlug)
      return { ok: false, error: "This site was created by a one-click app — remove it from the Apps tab." };
    await db.website.update({ where: { id }, data: { status: "DELETING" } });
    await db.job.create({ data: { type: "WEBSITE_DELETE", serverId: site.serverId, payload: { websiteId: id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.website.delete", detail: site.domain },
    });
    revalidatePath(`/dashboard/servers/${site.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/**
 * Inline (non-worker) quick reads for the control panel: service status and a
 * live process/resource snapshot. These are cheap, read-only SSH commands with a
 * short timeout, so they run inline from the server actions rather than via a
 * queued job (mirrors how lib/sftp.ts serves file listings inline).
 *
 * SANDBOX: on staging NO real SSH is ever opened — every read returns realistic,
 * deterministic synthetic data so the whole panel UX works end to end without a
 * live VM. Plain server module (no "use server"): imported by lib/actions-cron.ts.
 */
import { SANDBOX } from "./sandbox";
import { withServerSsh, exec, assertService, shellQuote, QUICK_TIMEOUT_MS } from "./ssh-exec";
import { COMMON_SERVICES, type ServiceStatus, type ProcessSnapshot } from "./cpanel-types";
import type { SftpServer } from "./sftp";

/** Deterministic pseudo-random in [0,1) from a string seed (sandbox realism). */
function seeded(seed: string): number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 10000) / 10000;
}

// ---------------------------------------------------------------------------
// Service status
// ---------------------------------------------------------------------------

/**
 * Status of the common services. In sandbox, nginx/ssh look running, php-fpm/
 * mysql installed-and-running, the rest a deterministic mix. On prod we ask
 * systemd for each unit in one round-trip.
 */
export async function readServiceStatuses(server: SftpServer): Promise<ServiceStatus[]> {
  if (SANDBOX) {
    return COMMON_SERVICES.map((s) => {
      let state: ServiceStatus["state"];
      if (s.unit === "nginx" || s.unit === "ssh") state = "running";
      else if (s.unit === "php-fpm" || s.unit === "mysql") state = "running";
      else state = seeded(server.id + s.unit) > 0.5 ? "running" : "not-installed";
      return { unit: s.unit, label: s.label, state };
    });
  }

  return withServerSsh(server, async (conn) => {
    const out: ServiceStatus[] = [];
    for (const s of COMMON_SERVICES) {
      assertService(s.unit);
      const q = shellQuote(s.unit);
      // is-active prints active/inactive/failed/unknown; if the unit doesn't
      // exist at all, `systemctl list-unit-files` finds nothing → not-installed.
      const r = await exec(
        conn,
        `if systemctl list-unit-files ${q}.service >/dev/null 2>&1 || systemctl status ${q} >/dev/null 2>&1; then ` +
          `systemctl is-active ${q} 2>/dev/null || echo inactive; else echo missing; fi`,
        QUICK_TIMEOUT_MS
      );
      const v = r.stdout.trim();
      let state: ServiceStatus["state"];
      if (v === "active") state = "running";
      else if (v === "missing") state = "not-installed";
      else if (v === "inactive" || v === "failed") state = "stopped";
      else state = "unknown";
      out.push({ unit: s.unit, label: s.label, state });
    }
    return out;
  });
}

// ---------------------------------------------------------------------------
// Process / resource snapshot
// ---------------------------------------------------------------------------

const SANDBOX_COMMANDS = [
  "nginx: worker process",
  "php-fpm: pool www",
  "mysqld",
  "node /var/www/app/server.js",
  "redis-server *:6379",
  "systemd --user",
  "sshd: root@pts/0",
];

export async function readProcessSnapshot(server: SftpServer): Promise<ProcessSnapshot> {
  if (SANDBOX) {
    const base = seeded(server.id);
    const cpuPct = Math.round((15 + base * 55) * 10) / 10;
    const memTotalMB = 4096;
    const memUsedMB = Math.round(memTotalMB * (0.35 + base * 0.4));
    const diskTotalGB = 80;
    const diskUsedGB = Math.round(diskTotalGB * (0.2 + base * 0.5) * 10) / 10;
    const top = SANDBOX_COMMANDS.map((command, i) => ({
      pid: 400 + i * 137 + Math.floor(seeded(server.id + i) * 90),
      user: i % 3 === 0 ? "root" : "www-data",
      cpu: Math.round(seeded(server.id + "c" + i) * 40 * 10) / 10,
      mem: Math.round(seeded(server.id + "m" + i) * 12 * 10) / 10,
      command,
    }))
      .sort((a, b) => b.cpu - a.cpu)
      .slice(0, 6);
    return {
      cpuPct,
      memUsedMB,
      memTotalMB,
      diskUsedGB,
      diskTotalGB,
      loadAvg: [
        Math.round(base * 2 * 100) / 100,
        Math.round(base * 1.6 * 100) / 100,
        Math.round(base * 1.2 * 100) / 100,
      ],
      uptimeSec: Math.floor(3600 * 24 * (2 + base * 20)),
      top,
    };
  }

  return withServerSsh(server, async (conn) => {
    // One fixed command bundle — no user input anywhere. Emits labelled lines we
    // parse below; robust to missing tools (best-effort fields).
    const script =
      "echo '#LOAD'; cat /proc/loadavg 2>/dev/null; " +
      "echo '#UP'; cat /proc/uptime 2>/dev/null; " +
      "echo '#MEM'; free -m 2>/dev/null | awk '/^Mem:/{print $2, $3}'; " +
      "echo '#DISK'; df -BG / 2>/dev/null | awk 'NR==2{gsub(/G/,\"\"); print $2, $3}'; " +
      "echo '#CPU'; awk '/^cpu /{u=$2+$4; t=$2+$4+$5; print u, t}' /proc/stat 2>/dev/null; " +
      "echo '#TOP'; ps -eo pid,user,pcpu,pmem,comm --sort=-pcpu 2>/dev/null | head -n 8";
    const r = await exec(conn, script, QUICK_TIMEOUT_MS);
    return parseSnapshot(r.stdout);
  });
}

/** Parse the labelled snapshot output into a ProcessSnapshot (best-effort). */
function parseSnapshot(out: string): ProcessSnapshot {
  const sections: Record<string, string[]> = {};
  let cur = "";
  for (const raw of out.split("\n")) {
    const line = raw.trimEnd();
    if (line.startsWith("#")) {
      cur = line.slice(1);
      sections[cur] = [];
    } else if (cur && line.trim().length) {
      sections[cur].push(line);
    }
  }
  const num = (s: string | undefined, d = 0) => {
    const n = Number(s);
    return Number.isFinite(n) ? n : d;
  };

  const load = (sections.LOAD?.[0] ?? "").split(/\s+/);
  const loadAvg: [number, number, number] = [num(load[0]), num(load[1]), num(load[2])];
  const uptimeSec = Math.floor(num((sections.UP?.[0] ?? "").split(/\s+/)[0]));
  const mem = (sections.MEM?.[0] ?? "").split(/\s+/);
  const memTotalMB = num(mem[0], 1);
  const memUsedMB = num(mem[1]);
  const disk = (sections.DISK?.[0] ?? "").split(/\s+/);
  const diskTotalGB = num(disk[0], 1);
  const diskUsedGB = num(disk[1]);
  const cpu = (sections.CPU?.[0] ?? "").split(/\s+/);
  const cpuBusy = num(cpu[0]);
  const cpuTotal = num(cpu[1], 1);
  const cpuPct = Math.round(Math.min(100, (cpuBusy / cpuTotal) * 100) * 10) / 10;

  const top = (sections.TOP ?? [])
    .filter((l) => !/^\s*PID\b/i.test(l))
    .map((l) => {
      const p = l.trim().split(/\s+/);
      return {
        pid: num(p[0]),
        user: p[1] ?? "?",
        cpu: num(p[2]),
        mem: num(p[3]),
        command: p.slice(4).join(" ") || "?",
      };
    })
    .slice(0, 6);

  return { cpuPct, memUsedMB, memTotalMB, diskUsedGB, diskTotalGB, loadAvg, uptimeSec, top };
}

