     3	import { useCallback, useEffect, useRef, useState } from "react";
     4	import { useRouter } from "next/navigation";
     5	import { createBackup, getBackupJob, type BackupJobStatus } from "@/lib/actions-server";
     6	
     7	const POLL_MS = 2500;
     8	/** A terminal (DONE/FAILED) job is only "fresh" enough to surface on load for a
     9	 *  short window — avoids nagging about an ancient failure on every page visit. */
    10	const FRESH_MS = 15 * 60 * 1000;
    11	
    12	function isInFlight(j: BackupJobStatus | null): j is BackupJobStatus {
    13	  return !!j && (j.status === "QUEUED" || j.status === "RUNNING");
    14	}
    15	
    16	function verbFor(type: BackupJobStatus["type"]): string {
    17	  return type === "BACKUP_RESTORE" ? "Restore" : "Backup";
    18	}
    19	
    20	/**
    21	 * Create-backup button + LIVE progress bar. Owns polling of the current
    22	 * backup/restore job (`getBackupJob`) so it renders a themed bar with the live
    23	 * percentage + step while a job is QUEUED/RUNNING, shows a "Backup failed —
    24	 * server unaffected" note on failure, and refreshes the backups list on success.
    25	 * Restores (enqueued elsewhere) surface here too since the poll covers both types.
    26	 */
    27	export function CreateBackupButton({
    28	  serverId,
    29	  disabled,
    30	  initialJob = null,
    31	}: {
    32	  serverId: string;
    33	  disabled?: boolean;
    34	  initialJob?: BackupJobStatus | null;
    35	}) {
    36	  const router = useRouter();
    37	  const [job, setJob] = useState<BackupJobStatus | null>(initialJob);
    38	  const [error, setError] = useState<string | null>(null);
    39	  const [queueing, setQueueing] = useState(false);
    40	  const [dismissed, setDismissed] = useState<string | null>(null);
    41	
    42	  // Ids we've observed in-flight this mount + the last status per id, so we can
    43	  // detect an in-flight → DONE transition and refresh the list exactly once.
    44	  const watched = useRef<Set<string>>(new Set());
    45	  const lastStatus = useRef<Record<string, string>>({});
    46	
    47	  const fetchJob = useCallback(async () => {
    48	    try {
    49	      const j = await getBackupJob(serverId);
    50	      if (isInFlight(j)) watched.current.add(j.id);
    51	      if (j) {
    52	        const prev = lastStatus.current[j.id];
    53	        // In-flight → DONE: the archive now exists, reload the backups table.
    54	        if (prev && prev !== j.status && j.status === "DONE" && watched.current.has(j.id)) {
    55	          router.refresh();
    56	        }
    57	        lastStatus.current[j.id] = j.status;
    58	      }
    59	      setJob(j);
    60	    } catch {
    61	      /* transient — keep last known state, next tick retries */
    62	    }
    63	  }, [serverId, router]);
    64	
    65	  useEffect(() => {
    66	    let cancelled = false;
    67	    let timer: ReturnType<typeof setTimeout>;
    68	    async function loop() {
    69	      if (cancelled) return;
    70	      await fetchJob();
    71	      if (!cancelled) timer = setTimeout(loop, POLL_MS);
    72	    }
    73	    loop();
    74	    return () => {
    75	      cancelled = true;
    76	      clearTimeout(timer);
    77	    };
    78	  }, [fetchJob]);
    79	
    80	  const inFlight = isInFlight(job);
    81	  const busy = queueing || inFlight;
    82	
    83	  // Terminal notes only for jobs we watched in-flight OR that are recent.
    84	  const relevant =
    85	    !!job &&
    86	    (watched.current.has(job.id) || Date.now() - new Date(job.createdAt).getTime() < FRESH_MS);
    87	  const showFailed = !!job && job.status === "FAILED" && relevant && dismissed !== job.id;
    88	
    89	  const pct = job?.progress ?? 0;
    90	  const verb = job ? verbFor(job.type) : "Backup";
    91	
    92	  return (
    93	    <div className="w-full space-y-4">
    94	      <div className="flex items-center justify-end gap-3">
    95	        {error && <span className="text-sm text-red-400">{error}</span>}
    96	        <button
    97	          className="btn-primary"
    98	          disabled={busy || disabled}
    99	          onClick={async () => {
   100	            setError(null);
   101	            setQueueing(true);
   102	            const res = await createBackup(serverId);
   103	            setQueueing(false);
   104	            if (res?.error) setError(res.error);
   105	            else fetchJob();
   106	          }}
   107	        >
   108	          {queueing ? "Queueing…" : inFlight ? `${verb} in progress…` : "Create backup"}
   109	        </button>
   110	      </div>
   111	
   112	      {inFlight && (
   113	        <div className="rounded-xl border border-white/10 bg-navy-950/60 p-4">
   114	          <div className="mb-2 flex items-center justify-between text-sm">
   115	            <span className="section-label">
   116	              {job.type === "BACKUP_RESTORE" ? "Restore in progress" : "Backup in progress"}
   117	            </span>
   118	            <span className="font-semibold tabular-nums">{pct}%</span>
   119	          </div>
   120	          <div className="h-2.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
   121	            <div
   122	              className="h-full rounded-full bg-brand-500 transition-all duration-500"
   123	              style={{ width: `${Math.max(3, pct)}%` }}
   124	            />
   125	          </div>
   126	          <p className="mt-2 text-sm text-slate-300">{job.step ?? "Starting…"}</p>
   127	        </div>
   128	      )}
   129	
   130	      {showFailed && (
   131	        <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 p-4">
   132	          <div className="flex items-center justify-between gap-3">
   133	            <p className="text-sm font-semibold text-amber-300">
   134	              {verb} failed — your server is unaffected
   135	            </p>
   136	            <button
   137	              className="text-xs text-slate-400 hover:text-slate-200"
   138	              onClick={() => setDismissed(job.id)}
   139	            >
   140	              Dismiss
