/**
 * Enqueue GAME_UPDATE jobs for every RUNNING game server that has opted into
 * auto-update and has no job already in flight. Idempotent / safe to call on a
 * timer. Returns nothing; logs a summary.
 */
export async function gameUpdateSweep(): Promise<void> {
  if (SANDBOX) return; // no game servers to update over SSH in the sandbox
  const candidates = await db.server.findMany({
    where: {
      status: "RUNNING",
      autoUpdate: true,
      osTemplate: { family: { in: [...GAME_FAMILIES] } },
    },
    select: { id: true, hostname: true },
  });
  if (candidates.length === 0) return;

  let enqueued = 0;
  for (const s of candidates) {
    const inflight = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (inflight > 0) continue;
    await db.job.create({ data: { type: "GAME_UPDATE", serverId: s.id } });
    enqueued++;
  }
  if (enqueued > 0) console.log(`[game-update] sweep enqueued ${enqueued} update job(s)`);
}
