 26	const RFB_URL = "/novnc/core/rfb.js";
 27	
 28	export function Console({ serverId }: { serverId: string }) {
 29	  const containerRef = useRef<HTMLDivElement>(null);
 30	  const rfbRef = useRef<any>(null);
 31	  const [phase, setPhase] = useState<Phase>("idle");
 32	  const [message, setMessage] = useState<string | null>(null);
 33	
 34	  const cleanup = useCallback(() => {
 35	    if (rfbRef.current) {
 36	      try {
 37	        rfbRef.current.disconnect();
 38	      } catch {
 39	        /* ignore */
 40	      }
 41	      rfbRef.current = null;
 42	    }
 43	  }, []);
 44	
 45	  useEffect(() => () => cleanup(), [cleanup]);
 46	
 47	  const connect = useCallback(async () => {
 48	    setMessage(null);
 49	    setPhase("loading");
 50	    cleanup();
 51	
 52	    // 1. Make sure the vendored noVNC assets are actually present.
 53	    try {
 54	      const head = await fetch(RFB_URL, { method: "HEAD", cache: "no-store" });
 55	      if (!head.ok) throw new Error("assets missing");
 56	    } catch {
 57	      setPhase("unavailable");
 58	      return;
 59	    }
 60	
 61	    // 2. Get a fresh single-use console ticket.
 62	    let ticket: { wsPath: string; ticketId: string };
 63	    try {
 64	      const res = await fetch(`/api/console/${serverId}`, { cache: "no-store" });
 65	      if (!res.ok) {
 66	        const body = (await res.json().catch(() => ({}))) as { error?: string };
 67	        throw new Error(body.error || "could not obtain a console ticket");
 68	      }
 69	      ticket = await res.json();
 70	    } catch (err) {
 71	      setPhase("error");
 72	      setMessage(err instanceof Error ? err.message : "could not obtain a console ticket");
 73	      return;
 74	    }
 75	
 76	    // 3. Load the vendored RFB client and connect to the relay.
 77	    let RFB: any;
 78	    try {
 79	      const mod = await importESM(RFB_URL);
 80	      RFB = mod.default ?? mod.RFB ?? mod;
 81	      if (typeof RFB !== "function") throw new Error("noVNC RFB module malformed");
 82	    } catch {
 83	      setPhase("unavailable");
 84	      return;
 85	    }
 86	
 87	    if (!containerRef.current) return;
 88	    setPhase("connecting");
 89	
 90	    try {
 91	      const rfb = new RFB(containerRef.current, ticket.wsPath, {
 92	        wsProtocols: ["binary"],
 93	      });
