167	            <button
168	              type="button"
169	              onClick={() => void connect()}
170	              className="btn-primary"
171	              disabled={phase === "loading"}
172	            >
173	              {phase === "loading" ? "Opening…" : "Open console"}
174	            </button>
175	          )}
176	        </div>
177	      </div>
178	
179	      {phase === "unavailable" ? (
180	        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
181	          <div className="flex items-start gap-3">
182	            <svg
183	              width="20"
184	              height="20"
185	              viewBox="0 0 24 24"
186	              fill="none"
187	              stroke="#fbbf24"
188	              strokeWidth="1.6"
189	              className="mt-0.5 shrink-0"
