import { NextRequest, NextResponse } from "next/server";
import { createHash, randomUUID } from "node:crypto";
import { EncryptJWT } from "jose";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { pve, node as primaryNode } from "@/lib/proxmox";

export const dynamic = "force-dynamic";

/**
 * In-browser VNC console — ticket issuer.
 *
 * GET /api/console/[serverId]
 *
 * Flow:
 *  1. Authenticate the caller (owner or admin).
 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
 *     an ephemeral port on the Proxmox node.
 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
 *     VNC ticket, and the API token needed to authenticate the websocket
 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
 *     unique jti so the relay can enforce single use.
 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
 *     which only the relay (sharing AUTH_SECRET) can decrypt.
 *
 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
 * credentials, and pipes bytes both ways.
 */

// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
// The relay derives the identical key the same way — no extra shared secret.
function consoleKey(): Uint8Array {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set");
  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
}

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  // Throttle ticket minting per user (falling back to IP) BEFORE we ask
  // Proxmox for a vncproxy ticket — each grant spawns an ephemeral vncproxy
  // process, so an unthrottled loop could orphan thousands of them.
  const xff = _req.headers.get("x-forwarded-for") ?? "";
  const ip = xff.split(",")[0]?.trim() || "unknown";
  const rl = checkRateLimit(`console:${user.id || ip}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many console requests — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { node: true },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  if (!server.vmid) {
    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
  }
  if (server.status !== "RUNNING") {
    return NextResponse.json(
      { error: "server must be running to open the console" },
      { status: 409 }
    );
  }

