// Compact panel for a single server page
// ---------------------------------------------------------------------------

export function ServerVolumesPanel({
  serverId,
  serverHostname,
  serverRunning,
  attached,
  available,
}: {
  serverId: string;
  serverHostname: string;
  serverRunning: boolean;
  /** Volumes currently attached to this server. */
  attached: VolumeRow[];
  /** Caller's DETACHED volumes that can be attached here (already ownership-filtered). */
  available: VolumeRow[];
}) {
  const [target, setTarget] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const attachable = useMemo(
    () => available.filter((v) => !v.serverId || v.serverId === serverId),
    [available, serverId]
  );

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      const res = await fn();
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="card p-5">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-base font-semibold">Block storage</h3>
          <p className="mt-1 text-sm text-slate-400">Add-on disks attached to this server.</p>
        </div>
      </div>

      {attached.length > 0 && (
        <div className="mt-4 space-y-2">
          {attached.map((v) => (
            <div
              key={v.id}
              className="flex items-center justify-between rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2"
            >
              <div className="text-sm">
                <span className="font-medium text-slate-100">{v.name}</span>{" "}
                <span className="text-slate-400">· {v.sizeGB} GB</span>
              </div>
              <div className="flex items-center gap-2">
                <StatusLabel status={v.status} />
                <button
                  className="btn-secondary px-3 py-1 text-xs"
                  disabled={pending || isBusy(v.status)}
                  onClick={() =>
                    run(
                      () => detachVolume(v.id),
                      `Detach "${v.name}" from ${serverHostname}? Data is preserved.`
                    )
                  }
                >
                  Detach
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="mt-4 flex flex-wrap items-center gap-2">
        <select
          className="input w-52 py-1.5 text-xs"
          value={target}
          onChange={(e) => setTarget(e.target.value)}
          disabled={pending || !serverRunning || attachable.length === 0}
        >
          <option value="">
            {attachable.length === 0 ? "No available volumes" : "Attach a volume…"}
          </option>
          {attachable.map((v) => (
            <option key={v.id} value={v.id}>
              {v.name} ({v.sizeGB} GB)
            </option>
          ))}
        </select>
        <button
          className="btn-secondary px-3 py-1 text-xs"
          disabled={pending || !target || !serverRunning}
          onClick={() => run(() => attachVolume(target, serverId))}
        >
          Attach
        </button>
        {!serverRunning && (
          <span className="text-xs text-slate-500">Server must be running to attach.</span>
        )}
      </div>

      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      {attached.length === 0 && (
        <p className="mt-3 text-xs text-slate-500">No volumes attached yet.</p>
      )}
    </div>
  );
}

