 54	 * family + its schema, the selected variant (defaulting to the schema default)
 55	 * and the stored settings values (validated/normalised against the schema so the
 56	 * UI always gets a complete, well-typed object).
 57	 */
 58	export async function getGameConfig(
 59	  serverId: string
 60	): Promise<{ error?: string; config?: GameConfigView }> {
 61	  const { server } = await ownedServer(serverId);
 62	
 63	  const family = familyFor(server);
 64	  const schema = schemaFor(family);
 65	  if (!family || !schema) {
 66	    return { error: "This server doesn't support game settings." };
 67	  }
 68	
